INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqowkhyz000ujtwca3eeny35',6,'To: All Staff
From: David Kim, Operations Manager
Date: March 15

Dear Team,

I am writing to _______ (1) you that our company will be relocating its headquarters to a new building on Oak Street beginning April 1. The new location has been _______ (2) chosen for its modern facilities and convenient public transport access.

All employees are requested to _______ (3) their personal belongings by March 28 so that the moving team can proceed efficiently. Please note that IT equipment will be handled separately by our technical staff.

For further questions, please do not hesitate to _______ (4) our facilities coordinator, Ms. Sarah Lim, at extension 204.

Thank you for your cooperation.

David Kim
Operations Manager','email');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqowkhyz000vjtwc2y41hbwq',6,'빈칸 (1)에 들어갈 알맞은 단어를 고르세요.','notify','notified','notifying','notification','A','[to 부정사 + 동사원형] to 부정사 구조에서 to 뒤에는 반드시 동사원형이 와야 합니다. 빈칸 앞 ''I am writing to''에서 to는 ''목적''을 나타내는 to 부정사이므로 동사원형인 A(notify / advise / conduct / offering 등 맥락에 따른 원형)가 정답입니다. 나머지 선택지는 과거분사, 현재분사, 명사형으로 to 부정사 자리에 올 수 없습니다.','to부정사','cmqowkhyz000ujtwca3eeny35');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqowkhyz000wjtwc9s8mwtjw',6,'빈칸 (2)에 들어갈 알맞은 단어를 고르세요.','careful','carefully','care','cares','B','[부사 vs 형용사] 빈칸 앞뒤 문맥을 확인하세요. 과거분사(has been chosen/streamlined 등)를 수식하거나 주어의 보어로 쓰일 때 각각 부사·형용사를 구분해야 합니다. 동사/분사를 수식하면 부사, 명사를 수식하거나 주어의 상태를 설명하면 형용사가 정답입니다. 나머지 선택지는 동사 원형 또는 명사형입니다.','품사','cmqowkhyz000ujtwca3eeny35');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqowkhyz000xjtwc3xidat83',6,'빈칸 (3)에 들어갈 알맞은 단어를 고르세요.','collecting','collected','collect','collection','C','[to 부정사 / 수동태] 빈칸이 to 부정사 자리라면 동사원형이 정답입니다. 수동태 be + p.p. 구조라면 과거분사가 정답입니다. 각 선택지를 문장에 대입해 ''주어와의 수동·능동 관계''를 확인하는 것이 핵심입니다. 전치사 뒤라면 동명사(-ing), 조동사 뒤라면 동사원형을 선택하세요.','to부정사','cmqowkhyz000ujtwca3eeny35');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqowkhyz000yjtwc7ihytwwd',6,'빈칸 (4)에 들어갈 알맞은 단어를 고르세요.','reach','reached','reaching','reaches','A','[품사 파악] 빈칸 앞뒤 구조를 분석해 어떤 품사가 필요한지 파악하는 것이 우선입니다. 관사(a/the) 또는 소유격 뒤라면 명사, 동사 뒤 명사 앞이라면 형용사 또는 부사, 조동사·to 뒤라면 동사원형을 선택합니다. 선택지의 어근이 같고 어미만 다를 경우 반드시 품사를 기준으로 판단하세요.','to부정사','cmqowkhyz000ujtwca3eeny35');
INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqowkhz1000zjtwcgmrd6kvq',6,'MEMORANDUM

To: All Department Supervisors
From: Human Resources Department
Re: Updated Leave Policy
Date: September 5

Please be _______ (1) that effective October 1, all annual leave requests must be submitted through the new online portal. This system will _______ (2) the approval process and reduce paperwork across all departments.

Employees who have already submitted leave requests through the previous method will not be _______ (3) to resubmit their applications. However, any new requests made after October 1 must be processed through the updated system.

Training sessions on the new portal will be held next week. Attendance is _______ (4) for all supervisors to ensure a smooth transition.','memo');
