INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqowkhz50019jtwco7ha10cd',6,'IMPORTANT MAINTENANCE NOTICE

Riverside Medical Center will be _______ (1) scheduled maintenance on all elevators from Friday, August 8, to Sunday, August 10. During this period, elevator service will be temporarily unavailable.

We sincerely apologize for any _______ (2) this may cause to our patients and visitors. Staff members will be available to assist anyone requiring help with mobility.

_______ (3), all medical departments and emergency services will remain fully operational during the maintenance period. Stairwell access will be available at all times.

We appreciate your _______ (4) and understanding during this necessary maintenance period.','notice');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqowkhz6001ajtwccaazvwrl',6,'빈칸 (1)에 들어갈 알맞은 단어를 고르세요.','conduct','conducted','conducting','conduction','C','[to 부정사 + 동사원형] to 부정사 구조에서 to 뒤에는 반드시 동사원형이 와야 합니다. 빈칸 앞 ''I am writing to''에서 to는 ''목적''을 나타내는 to 부정사이므로 동사원형인 A(notify / advise / conduct / offering 등 맥락에 따른 원형)가 정답입니다. 나머지 선택지는 과거분사, 현재분사, 명사형으로 to 부정사 자리에 올 수 없습니다.','동사 시제','cmqowkhz50019jtwco7ha10cd');
