INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqowkhz6001cjtwc6qgvs629',6,'빈칸 (3)에 들어갈 알맞은 단어를 고르세요.','Therefore','However','Please note that','As a result','C','[to 부정사 / 수동태] 빈칸이 to 부정사 자리라면 동사원형이 정답입니다. 수동태 be + p.p. 구조라면 과거분사가 정답입니다. 각 선택지를 문장에 대입해 ''주어와의 수동·능동 관계''를 확인하는 것이 핵심입니다. 전치사 뒤라면 동명사(-ing), 조동사 뒤라면 동사원형을 선택하세요.','접속부사','cmqowkhz50019jtwco7ha10cd');
