INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqqaxmwg000uchwcx9xd9m0d',6,'To: All Department Managers
From: Jennifer Walsh, HR Director
Date: October 3
Subject: Updated Annual Leave Policy

I am writing to inform you of important changes to our company''s annual leave policy. Effective November 1, all employees will be entitled to 15 days of paid annual leave per year, --------(131) from the current 12 days. This change reflects the company''s --------(132) to employee well-being and work-life balance.

Managers are asked to --------(133) their teams about this update as soon as possible. Please note that unused leave days from this year may not be carried over to the following year. --------(134)

If you have any questions regarding the new policy, please do not hesitate to contact the HR department.

Best regards,
Jennifer Walsh
HR Director','email');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwi000vchwc73eilj6r',6,'131. (A) increase  (B) increased  (C) increasing  (D) increases','increase','increased','increasing','increases','B','분사구문으로 과거분사 increased(증가된)가 앞 명사를 수식합니다.','verb form','cmqqaxmwg000uchwcx9xd9m0d');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwi000wchwcky6aw6ck',6,'132. (A) commit  (B) committed  (C) commitment  (D) commits','commit','committed','commitment','commits','C','소유격(company''s) 뒤에 명사 commitment(헌신)가 필요합니다.','part of speech','cmqqaxmwg000uchwcx9xd9m0d');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwk000xchwc7bzxui8z',6,'133. (A) informing  (B) inform  (C) informed  (D) informative','informing','inform','informed','informative','B','asked to 뒤에는 동사원형이 옵니다.','verb form','cmqqaxmwg000uchwcx9xd9m0d');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwl000ychwc5u5v4lhk',6,'134. Which of the following sentences best fits in the blank?','However, you may apply for an extension in exceptional circumstances.','The new policy will be implemented starting January 1 of next year.','Employees are therefore encouraged to use their leave throughout the year.','All leave requests must be approved by HR at least two weeks in advance.','C','미사용 연차가 이월되지 않는다는 맥락 뒤에 연차 사용을 권장하는 문장이 자연스럽습니다.','sentence insertion','cmqqaxmwg000uchwcx9xd9m0d');
INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqqaxmwl000zchwcy9zfnnel',6,'Bright Star Conference Center

Planning your next corporate event? Bright Star Conference Center is the --------(135) choice for businesses throughout the region. Our facilities include state-of-the-art audio-visual equipment, high-speed Internet access, and comfortable seating for --------(136) 500 guests.

We also offer various catering options to suit every budget and dietary requirement. Our --------(137) event coordination team will ensure that every aspect of your event runs smoothly. --------(138)

Contact us today at 555-0184 or visit www.brightstarcenter.com to check availability and pricing.','advertisement');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwm0010chwce3l15rpf',6,'135. (A) ideal  (B) ideally  (C) idealize  (D) idealism','ideal','ideally','idealize','idealism','A','명사(choice) 앞에서 수식하는 형용사 ideal이 필요합니다.','part of speech','cmqqaxmwl000zchwcy9zfnnel');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwm0011chwcvqrez2z2',6,'136. (A) up to  (B) as far as  (C) as well as  (D) due to','up to','as far as','as well as','due to','A','숫자 앞에서 최대 수용 인원을 나타낼 때 up to를 사용합니다.','preposition','cmqqaxmwl000zchwcy9zfnnel');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwn0012chwcxmdh53ea',6,'137. (A) dedicate  (B) dedicated  (C) dedicating  (D) dedication','dedicate','dedicated','dedicating','dedication','B','명사(team) 앞에서 수식하는 형용사 역할의 과거분사 dedicated가 필요합니다.','part of speech','cmqqaxmwl000zchwcy9zfnnel');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwn0013chwcnry5w8dl',6,'138. Which of the following sentences best fits in the blank?','Our center has been in operation for over twenty years.','We look forward to making your event an unforgettable experience.','Parking is available in the underground garage for an additional fee.','Please note that all bookings must be made at least 30 days in advance.','B','광고 마무리로 긍정적인 기대감을 표현하는 B가 가장 자연스럽습니다.','sentence insertion','cmqqaxmwl000zchwcy9zfnnel');
INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqqaxmwn0014chwc38mz18l4',7,'Heritage Bookshop — Grand Reopening

After six months of renovations, Heritage Bookshop is proud to announce its grand reopening on Saturday, April 5, from 10 A.M. to 8 P.M.

Visit us at our new location at 245 Cedar Street, just two blocks from Central Station. We have expanded our collection to include over 50,000 titles across all genres, and we have added a cozy café serving freshly brewed coffee and homemade pastries.

To celebrate our reopening, all purchases of $30 or more will receive a complimentary tote bag while supplies last. Heritage Bookshop members will also enjoy an exclusive 20% discount throughout the entire month of April.

Not a member yet? Sign up in-store on reopening day and receive your first year of membership for free.','notice');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwp0015chwcer37hi2g',7,'What is indicated about Heritage Bookshop?','It has recently moved to a new location.','It was founded six months ago.','It offers online purchasing options.','It is the largest bookshop in the area.','A','지문에서 new location으로 이전했다고 명시되어 있습니다.','detail','cmqqaxmwn0014chwc38mz18l4');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwp0016chwcwqwnxl56',7,'What benefit is available to customers who spend at least $30?','Free membership for one year','A complimentary tote bag','A 20% discount','A free cup of coffee','B','$30 이상 구매 시 complimentary tote bag을 받는다고 명시되어 있습니다.','detail','cmqqaxmwn0014chwc38mz18l4');
INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqqaxmwq0017chwcskv1b94f',7,'To: Customer Service <customerservice@greenlane.com>
From: Margaret Holloway <mholloway@email.com>
Date: June 14
Subject: Delivery Issue — Order #GH7821

Dear Customer Service,

I placed an order on June 8 for a set of outdoor garden furniture (Order #GH7821). According to your website, the estimated delivery date was June 12. However, it is now June 14, and I have not yet received my order.

I have attempted to track my package through your online portal, but the tracking information has not been updated since June 9, when the order was marked as "shipped."

I would appreciate it if you could look into this matter and provide me with an update as soon as possible. If the items cannot be delivered by June 20, I would like to request a full refund.

Thank you for your assistance.

Sincerely,
Margaret Holloway','email');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwr0018chwchdvs4tu6',7,'Why is Ms. Holloway writing to Customer Service?','To request a refund for a damaged item','To inquire about a delayed delivery','To cancel an order she placed online','To report a problem with the website','B','주문한 물건이 예정일이 지나도 오지 않아 문의하는 이메일입니다.','purpose','cmqqaxmwq0017chwcskv1b94f');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwr0019chwc7u179hjw',7,'When was the order placed?','June 8','June 9','June 12','June 14','A','I placed an order on June 8라고 명시되어 있습니다.','detail','cmqqaxmwq0017chwcskv1b94f');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmws001achwc5dxcgbg6',7,'What does Ms. Holloway indicate about the tracking information?','It shows the package has already been delivered.','It was last updated on June 9.','It is unavailable on the website.','It shows the wrong delivery address.','B','tracking information has not been updated since June 9라고 명시되어 있습니다.','detail','cmqqaxmwq0017chwcskv1b94f');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmws001bchwcsocqglao',7,'What does Ms. Holloway request if her order does not arrive by June 20?','A replacement for the item','A discount on her next purchase','A full refund','Expedited shipping at no charge','C','If the items cannot be delivered by June 20, I would like to request a full refund라고 명시되어 있습니다.','detail','cmqqaxmwq0017chwcskv1b94f');
INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqqaxmwt001cchwcyzpd4s89',7,'[Notice]
Lakeside Community Center

Attention: All Members

Please be advised that the Lakeside Community Center will be closed for scheduled maintenance from Monday, March 10, to Wednesday, March 12. During this time, the swimming pool, fitness center, and all meeting rooms will be unavailable.

Normal operating hours will resume on Thursday, March 13, beginning at 7:00 A.M. Members who have scheduled appointments or reserved meeting rooms during the closure period should contact our reception desk at 555-0291 to reschedule.

We apologize for any inconvenience this may cause.
— The Management Team, Lakeside Community Center

---

[E-mail]
To: Lakeside Community Center <info@lakesidecc.com>
From: Daniel Frost <dfrost@hartleytech.com>
Date: March 7
Subject: Room Reservation Inquiry

Dear Management Team,

I am writing regarding our reservation for Conference Room B on March 11 from 2:00 P.M. to 5:00 P.M. (Reservation #LCC-0482). We plan to use the room for a team training session for approximately 15 people.

I recently saw the notice about the upcoming maintenance closure and wanted to confirm whether our reservation will be affected. If the room will not be available on March 11, we would like to reschedule to March 14 at the same time, if possible.

Please let me know at your earliest convenience so that I can inform my team members accordingly.

Thank you,
Daniel Frost, Hartley Technology','double passage');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwt001dchwc0x06bp6u',7,'Why is the community center closing temporarily?','For staff training','For building renovations','For scheduled maintenance','For a special community event','C','공지에 scheduled maintenance(정기 유지보수)로 인해 폐관한다고 명시되어 있습니다.','purpose','cmqqaxmwt001cchwcyzpd4s89');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwt001echwc3mpwylu5',7,'What are members with existing reservations asked to do?','Log in to the center''s Web site','Contact the reception desk','Send an e-mail to the management team','Visit the center in person','B','공지에서 contact our reception desk at 555-0291라고 안내하고 있습니다.','detail','cmqqaxmwt001cchwcyzpd4s89');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwu001fchwczpkwajq6',7,'What is the purpose of Mr. Frost''s e-mail?','To inquire about membership renewal','To confirm whether his reservation will be affected by the closure','To report a problem with the booking system','To cancel a previously made reservation','B','예약이 유지보수 폐관에 영향을 받는지 확인하고 필요시 재예약을 요청하는 이메일입니다.','purpose','cmqqaxmwt001cchwcyzpd4s89');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwu001gchwcizxdmvt8',7,'How many people does Mr. Frost plan to bring to the training session?','About 5','About 10','About 15','About 20','C','이메일에서 approximately 15 people이라고 명시되어 있습니다.','detail','cmqqaxmwt001cchwcyzpd4s89');
INSERT OR IGNORE INTO "Question" ("id","part","questionText","optionA","optionB","optionC","optionD","answer","explanation","category","groupId") VALUES ('cmqqaxmwv001hchwch4n4hyu2',7,'If Mr. Frost''s reservation needs to be rescheduled, what date does he prefer?','March 10','March 12','March 13','March 14','D','이메일에서 reschedule to March 14 at the same time이라고 명시되어 있습니다.','detail','cmqqaxmwt001cchwcyzpd4s89');
INSERT OR IGNORE INTO "QuestionGroup" ("id","part","passageText","passageType") VALUES ('cmqqaz0x9000udcwcz4f21fu8',7,'[공지문]
To: All Staff
From: Jennifer Wu, HR Director
Subject: Annual Employee Recognition Gala — Nominations Open

The Hartfield Group is pleased to announce that nominations are now open for the Annual Employee Recognition Gala, to be held on Friday, October 17, at the Grand Meridian Hotel. This year, we will be recognizing outstanding employees in four categories: Innovation, Leadership, Customer Excellence, and Team Collaboration.

All employees are eligible to nominate a colleague. Nominations must be submitted via the company intranet portal by September 19. Each nominee requires a written statement of no more than 200 words explaining why they deserve the award.

A reception and dinner will be held beginning at 6:30 P.M., followed by the award ceremony at 8:00 P.M. Attendance is open to all staff. Please RSVP through the HR portal by October 3.

---

[이메일]
To: jennifer.wu@hartfieldgroup.com
From: Marcus Reynolds <m.reynolds@hartfieldgroup.com>
Date: September 15
Subject: RE: Annual Employee Recognition Gala — Nominations Open

Dear Ms. Wu,

Thank you for the announcement regarding the Employee Recognition Gala. I would like to nominate my colleague, Dr. Sarah Lim of the Product Development team, for the Innovation award.

Dr. Lim led the redesign of our flagship product''s core module this year, reducing production costs by 18 percent while improving output quality. Her cross-departmental approach to problem-solving has significantly influenced how our teams collaborate.

I have attached a 185-word nomination statement as requested. Please let me know if any additional information is required.

Best regards,
Marcus Reynolds
Senior Engineer, Product Development

---

[확인 이메일]
To: m.reynolds@hartfieldgroup.com
From: HR Department <hr@hartfieldgroup.com>
Date: September 16
Subject: Nomination Received — Employee Recognition Gala

Dear Mr. Reynolds,

Thank you for submitting your nomination for the Annual Employee Recognition Gala. We are pleased to confirm that your nomination for Dr. Sarah Lim for the Innovation Award has been received and is under review.

The Nominations Committee will evaluate all submissions and notify nominees by September 30. Winners will be announced at the ceremony on October 17.

Please note that nominees are not to be informed of their nomination until after the winners are announced. If you have any questions, contact hr@hartfieldgroup.com.

The HR Team
Hartfield Group','triple passage');
